package com.dukaops.backend.sales; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import jakarta.validation.Valid; import com.dukaops.backend.auth.TenantUserPrincipal; import com.dukaops.backend.sales.dto.*; import org.springframework.data.domain.Page;
@RestController @RequestMapping("/api/sales") public class SalesController { private final SalesService service; public SalesController(SalesService s){service=s;} @PostMapping("/checkout") public SalesOrderResponse checkout(@AuthenticationPrincipal TenantUserPrincipal p,@Valid @RequestBody CheckoutRequest r){return service.checkout(p,r);} @GetMapping("/orders") public Page<SalesOrderResponse> orders(@AuthenticationPrincipal TenantUserPrincipal p,@RequestParam(required=false)String search,@RequestParam(required=false)OrderStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(p,search,status,page,size);} @GetMapping("/orders/{id}") public SalesOrderDetailResponse detail(@AuthenticationPrincipal TenantUserPrincipal p,@PathVariable java.util.UUID id){return service.detail(p,id);} @PatchMapping("/orders/{id}/status") public SalesOrderResponse status(@AuthenticationPrincipal TenantUserPrincipal p,@PathVariable java.util.UUID id,@Valid @RequestBody UpdateOrderStatusRequest r){return service.updateStatus(p,id,r.status());} @GetMapping("/summary") public SalesSummaryResponse summary(@AuthenticationPrincipal TenantUserPrincipal p){return service.summary(p);} }
